$ErrorActionPreference='Stop'
$root='F:\JericoEngine\JericoEngine';$base=Join-Path $root 'build\n0-validation\local-packages';$build=Join-Path $base 'python-v143-rev2\consumer-retry';$package=Join-Path $base 'python-v143-rev2\extracted\python-3.10.13-je-rev1-windows';$freeze=Join-Path $base 'source-freeze-python-parent-rev2.json';$cmake='C:\Program Files\CMake\bin\cmake.exe';$msbuild='C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools\MSBuild\Current\Bin\MSBuild.exe';$prefix=Join-Path $base 'python-consumer-retry-build-debug'
function Snapshot-Inputs([string]$label){$mf=Get-Content -LiteralPath $freeze -Raw|ConvertFrom-Json;$ss=@($mf|ForEach-Object{$p=Join-Path $root $_.path;[pscustomobject]@{path=$_.path;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash}});$ps=@(Get-ChildItem -LiteralPath $package -File -Recurse|ForEach-Object{$h=Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256;[pscustomobject]@{path=$_.FullName.Substring($package.Length).TrimStart('\');bytes=$_.Length;sha256=$h.Hash}}|Sort-Object path);$dest="$prefix-package-$label.json";$ps|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $dest -Encoding UTF8;[pscustomobject]@{freeze_sha256=(Get-FileHash -LiteralPath $freeze -Algorithm SHA256).Hash;source=$ss;package_files=$ps.Count;package_bytes=($ps|Measure-Object bytes -Sum).Sum;package_snapshot=$dest;archive_sha256=(Get-FileHash -LiteralPath (Join-Path (Split-Path $package -Parent|Split-Path -Parent) 'package-retry\python-3.10.13-je-rev1-windows.tar.xz') -Algorithm SHA256).Hash;cmake_sha256=(Get-FileHash -LiteralPath $cmake -Algorithm SHA256).Hash;msbuild_sha256=(Get-FileHash -LiteralPath $msbuild -Algorithm SHA256).Hash}}
$a1='--build';$a2=$build;$a3='--config';$a4='Debug';$a5='--target';$a6='JEPythonEmbed';[string[]]$argv=@($a1,$a2,$a3,$a4,$a5,$a6);if($argv.Count -ne 6 -or $argv[0] -ne '--build' -or $argv[2] -ne '--config' -or $argv[4] -ne '--target'){throw 'build argv invalid'}
$env:PIP_NO_INDEX='1';$env:PIP_DISABLE_PIP_VERSION_CHECK='1';$env:PYTHONNOUSERSITE='1';$meta=[pscustomobject]@{cwd=(Get-Location).Path;executable=$cmake;argv=@($argv);argv_count=$argv.Count;mode='build Debug';started=(Get-Date).ToString('o');inputs_before=(Snapshot-Inputs 'before')};$meta|ConvertTo-Json -Depth 8|Set-Content -LiteralPath "$prefix-argv-before.json" -Encoding UTF8
$sw=[Diagnostics.Stopwatch]::StartNew();$output=& $cmake @argv 2>&1;$exit=$LASTEXITCODE;$sw.Stop();$output|Out-String|Set-Content -LiteralPath "$prefix.log" -Encoding UTF8;$exit|Set-Content -LiteralPath "$prefix.exitcode" -Encoding ASCII;('{0:N3}s' -f $sw.Elapsed.TotalSeconds)|Set-Content -LiteralPath "$prefix.elapsed.txt" -Encoding ASCII;$after=Snapshot-Inputs 'after';[pscustomobject]@{started=$meta.started;finished=(Get-Date).ToString('o');exitcode=$exit;elapsed_seconds=$sw.Elapsed.TotalSeconds;before=$meta.inputs_before;after=$after}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath "$prefix-inputs-after.json" -Encoding UTF8;Write-Output ("exit=$exit elapsed={0:N3}s" -f $sw.Elapsed.TotalSeconds)
